async function dataURL(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('文件读取失败'));r.readAsDataURL(file)})}
async function photo(file){if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('请选择JPG、PNG或WebP照片');if(file.size>20*1024*1024)throw Error('原照片请小于20MB');const raw=await dataURL(file),image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('照片无法打开'));image.src=raw});const scale=Math.min(1,1600/image.width,1600/image.height),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.86)}
async function recordVoice(){if(recorder?.state==='recording'){recorder.stop();return}if(!navigator.mediaDevices?.getUserMedia||!window.isSecureContext){toast('当前连接不能直接录音，请用“选择录音文件”上传系统录音。');return}try{recordStream=await navigator.mediaDevices.getUserMedia({audio:true});const chunks=[];recorder=new MediaRecorder(recordStream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=async()=>{clearTimeout(recordTimer);recordStream?.getTracks().forEach(t=>t.stop());const blob=new Blob(chunks,{type:recorder.mimeType});if(blob.size>2*1024*1024){toast('录音超过2MB，请缩短后重录');return}voiceData=await dataURL(blob);if($('#voicePreview'))$('#voicePreview').innerHTML=`<audio controls src="${voiceData}" aria-label="老师录音预览"></audio>`;if($('#recordStatus'))$('#recordStatus').textContent='录音已准备好，随点评一起发送。';const b=$('[data-action="record"]');if(b)b.textContent='重新录音'};recorder.start();$('#recordStatus').textContent='正在录音，点击结束；60秒后自动结束。';$('[data-action="record"]').textContent='结束录音';recordTimer=setTimeout(()=>{if(recorder?.state==='recording')recorder.stop()},60000)}catch(e){toast('没有取得录音权限，可以改用录音文件。')}}
function stopRecording(){clearTimeout(recordTimer);if(recorder?.state==='recording'){recorder.onstop=null;recorder.stop()}recordStream?.getTracks().forEach(t=>t.stop())}
async function handleForm(form){const d=Object.fromEntries(new FormData(form).entries()),kind=form.dataset.form;let result;if(kind==='heroPreview'){MoyaGame.applyHeroPreview(d.level);return}if(kind==='renamePet'){await studentAction({action:'renamePet',petId:d.petId,name:d.name},'伙伴的新名字已记住');closeModal();return}if(kind==='bootstrap'||kind==='login'){result=await api('/api/'+kind,d);csrf=result.csrfToken;view='';await refresh();return}if(kind==='password'){await api('/api/password',d);S=null;csrf='';view='';closeModal();auth(false);toast('密码已修改，请重新登录。');return}else if(kind==='parentPassword'){result=await api('/api/students/'+d.studentId+'/reset-parent-password',{newPassword:d.newPassword})}else if(kind==='archive'){result=await api('/api/assignments/'+d.assignmentId+'/archive',{reason:d.reason})}else if(kind==='class')result=await api('/api/classes',{name:d.name,teacherIds:[d.teacherId]});else if(kind==='teacher')result=await api('/api/teachers',d);else if(kind==='student')result=await api('/api/students',d);else if(kind==='assignment'){const [scope,id]=d.target.split(':');delete d.target;d[scope==='class'?'classId':'studentId']=id;d.characters=d.characters.split(/\s+/).filter(Boolean);result=await api('/api/assignments',d)}else if(kind==='submission'){result=await api('/api/students/'+studentId+'/submissions',{assignmentId:d.assignmentId,day:taskDay,image:await photo(form.elements.image.files[0])})}else if(kind==='review'){if(recorder?.state==='recording')throw Error('请先结束录音，试听后再送出点评');result=await api('/api/submissions/'+d.submissionId+'/review',{grade:d.grade,comment:d.comment,...voiceData?{voice:voiceData}:{}})}else if(kind==='attendance')result=await api('/api/students/'+d.studentId+'/attendance',{lessonId:d.lessonId,day:d.day});else if(kind==='gift')result=await api('/api/students/'+d.studentId+'/gifts',{item:d.item,count:Number(d.count),reason:d.reason});else if(kind==='restore'){result=await api('/api/restore',{backup:restoreFile,confirm:d.confirm});S=null;csrf='';view='';closeModal();auth(false);toast('恢复完成，请用备份里的账号重新登录。');return}closeModal();await refresh();if(kind==='student'){modal(`<span class="pill">新同学已加入</span><h2>${E(result.name||d.name)}，欢迎你</h2><p>请将下面的账号私下交给家长。</p><div class="credentials"><b>账号：${E(result.guardianCredentials?.username||d.guardianUsername)}</b><b>初始密码：${E(result.guardianCredentials?.password||d.guardianPassword)}</b></div><p class="hint">密码只在此处展示，不会在班级列表公开。</p><button class="primary wide" data-action="close">我已经妥善记录</button>`)}else if(kind==='submission'&&result.event){result.event.submission=true;celebration(result.event,'今天的认真，收到了！')}else toast(kind==='review'?'点评已送到孩子的作品册':kind==='parentPassword'?'家长密码已更新，请私下交接。':'已保存')}
document.addEventListener('click',e=>{const icon=e.target.closest('[data-model-item]');if(icon){e.preventDefault();if(busy)return;actions.itemDetail({dataset:{id:icon.dataset.modelItem}});return}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const fn=actions[b.dataset.action];if(fn)Promise.resolve().then(()=>fn(b)).catch(e=>toast(e.message))});document.addEventListener('submit',async e=>{const f=e.target;if(!f.matches('[data-form]'))return;e.preventDefault();if(busy)return;busy=true;const b=f.querySelector('button[type="submit"],button:not([type])'),old=b?.textContent;if(b){b.disabled=true;b.textContent='正在保存…'}try{await handleForm(f)}catch(e){const err=f.querySelector('.form-error');if(err)err.textContent=e.message;else toast(e.message)}finally{busy=false;if(b?.isConnected){b.disabled=false;b.textContent=old}}});
document.addEventListener('keydown',e=>{const icon=e.target.closest?.('[data-model-item]');if(icon&&['Enter',' '].includes(e.key)){e.preventDefault();actions.itemDetail({dataset:{id:icon.dataset.modelItem}})}});document.addEventListener('change',async e=>{try{const t=e.target;if(t.id==='childSelect'){studentId=t.value;mapStart=null;await loadTasks();render()}if(t.id==='taskDate'){taskDay=t.value;await loadTasks();render()}if(t.id==='reviewFilter')$('#reviewList').innerHTML=S.submissions.filter(s=>t.value==='all'||(t.value==='pending'?!s.grade:!!s.grade)).slice().reverse().map(submissionCard).join('')||empty('这里暂时没有作品','稍后可以再看看。');if(t.id==='portfolioFilter')$('#portfolioList').innerHTML=S.submissions.filter(s=>s.studentId===studentId&&(t.value==='all'||s.category===t.value)).slice().reverse().map(portfolioCard).join('')||empty('这类作品还没开始','每一幅都会留下足迹。');if(t.id==='submissionImage'&&t.files[0])$('#photoPreview').innerHTML=`<img src="${await photo(t.files[0])}" alt="待提交作业照片预览">`;if(t.id==='voiceFile'&&t.files[0]){if(!t.files[0].type.startsWith('audio/')||t.files[0].size>2*1024*1024)throw Error('请选择不超过2MB的音频文件');voiceData=await dataURL(t.files[0]);$('#voicePreview').innerHTML=`<audio controls src="${voiceData}" aria-label="老师录音预览"></audio>`;$('#recordStatus').textContent='录音已准备好。'}}catch(e){toast(e.message)}});$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal()});document.addEventListener('play',e=>{if(e.target.tagName==='AUDIO')MoyaAudio.stopAll()},true);document.addEventListener('visibilitychange',()=>{if(document.hidden)petMessage({...petPayload(),paused:true});else petMessage(petPayload())});if('serviceWorker'in navigator)navigator.serviceWorker.register('/school-sw.js').catch(()=>{});setInterval(()=>{if(S&&!busy&&!$('#modal').open&&view!=='companion'&&!document.hidden)void refresh().catch(()=>{})},45000);boot();
